"""Write the two synthetic cross-reference-layout fixtures (re-run after editing):

    python tests/fixtures/parsing/build_xref_fixtures.py

- `xref_bank_style.htm` copies JPM's layout: Part I in the 10-K wrapper, then a "Form
  10-K cross-reference index" whose rows are one-row tables (`Item 7. | Management's
  discussion and analysis | 50-160`), so Items 7 and 8 come out as ~400-character stubs
  and Item 15 swallows the whole annual report. MD&A pages repeat the running header
  "Management's discussion and analysis"; the real MD&A opens with "The following is
  Management's discussion and analysis ..." (curly apostrophe).
- `xref_energy_style.htm` copies XOM's layout: "Items 1 and 2", Item 7 and Item 8 that
  only say "Reference is made to ... the Financial Section", and the Financial Section
  after Item 16 and the signatures, with its own table of contents ("Report of
  Independent Registered Public Accounting Firm | 69") and the running header
  "MANAGEMENT'S DISCUSSION AND ANALYSIS OF FINANCIAL CONDITION AND RESULTS OF
  OPERATIONS" every page (20 to 40 lines).

Everything is made up: company names, numbers and sentences are generated from a fixed
seed, so the output is identical on every run.
"""

import random
from html import escape
from pathlib import Path

HERE = Path(__file__).parent

SUBJECTS = [
    "Net revenue",
    "Noninterest expense",
    "The provision for credit losses",
    "Net interest income",
    "Average deposits",
    "Operating cash flow",
    "Capital expenditures",
    "Upstream earnings",
    "Refining margin",
    "Chemical sales volume",
]
VERBS = ["increased", "decreased", "was largely unchanged at", "rose to", "declined to"]
REASONS = [
    "driven by higher rates on interest-earning assets",
    "reflecting lower realized prices across most regions",
    "primarily due to growth in average loan balances",
    "as cost savings offset inflationary pressure on wages",
    "on the timing of scheduled maintenance at two facilities",
    "partially offset by higher legal expense in the period",
    "consistent with the outlook described in the prior year",
    "mainly from favorable foreign exchange movements",
]


def sentence(rng: random.Random) -> str:
    amount = f"${rng.randint(1, 99)}.{rng.randint(0, 9)} billion"
    return f"{rng.choice(SUBJECTS)} {rng.choice(VERBS)} {amount} in 2025, {rng.choice(REASONS)}."


def paragraph(rng: random.Random, n: int = 6) -> str:
    return " ".join(sentence(rng) for _ in range(n))


def div(text: str, bold: bool = False) -> str:
    style = ' style="font-weight:700"' if bold else ""
    return f"<div><span{style}>{escape(text, quote=False)}</span></div>"


def table(rows: list[list[str]]) -> str:
    cells = "".join(
        "<tr>" + "".join(f"<td>{escape(c, quote=False)}</td>" for c in row) + "</tr>"
        for row in rows
    )
    return f"<table>{cells}</table>"


def data_table(rng: random.Random, label: str) -> str:
    rows = [["", "2025", "2024", "2023"]]
    for i in range(6):
        rows.append([f"{label} line {i + 1}", *(f"{rng.randint(100, 99999):,}" for _ in range(3))])
    return table(rows)


def page_break() -> str:
    return '<hr style="page-break-after:always"/>'


def document(title: str, parts: list[str]) -> str:
    body = "\n".join(parts)
    return (
        '<?xml version="1.0" encoding="utf-8"?>\n'
        f"<!-- Synthetic fixture: {title}. Generated by build_xref_fixtures.py. "
        "Not real SEC data. -->\n"
        f'<html xmlns="http://www.w3.org/1999/xhtml">\n<body>\n{body}\n</body>\n</html>\n'
    )


def part_one(rng: random.Random, combined_items: bool) -> list[str]:
    out = [div("PART I")]
    if combined_items:
        out.append(div("ITEMS 1 AND 2. BUSINESS AND PROPERTIES", bold=True))
    else:
        out.append(div("Item 1. Business", bold=True))
    out += [div(paragraph(rng)) for _ in range(6)]
    out.append(div("Item 1A. Risk Factors", bold=True))
    out += [div(paragraph(rng)) for _ in range(6)]
    out += [div("Item 1B. Unresolved Staff Comments", bold=True), div("None.")]
    out += [div("Item 1C. Cybersecurity", bold=True), div(paragraph(rng, 3))]
    if not combined_items:
        out += [div("Item 2. Properties", bold=True), div(paragraph(rng, 2))]
    out += [div("Item 3. Legal Proceedings", bold=True), div(paragraph(rng, 2))]
    out += [div("Item 4. Mine Safety Disclosures", bold=True), div("Not applicable.")]
    return out


def bank_style() -> str:
    """JPM's layout: a cross-reference index, then the whole annual report in Item 15."""
    rng = random.Random(7)
    header = "Management’s discussion and analysis"
    notes_header = "Notes to consolidated financial statements"
    out = [div("UNITED STATES SECURITIES AND EXCHANGE COMMISSION"), div("FORM 10-K")]
    out.append(div("Example Bank Corp."))
    out.append(table([["Part I", "Page"], ["Item 1. Business", "1"], ["Item 1A. Risk", "4"]]))
    out.append(page_break())
    out += part_one(rng, combined_items=False)
    out.append(div("Form 10-K cross-reference index", bold=True))
    index_rows = [
        ["Item 5.", "Market for registrant’s common equity", "30"],
        ["Item 6.", "[Reserved]", "30"],
        ["Item 7.", "Management’s discussion and analysis", "50–160"],
        ["Item 7A.", "Quantitative and qualitative disclosures about market risk", "161"],
        ["Item 8.", "Financial statements and supplementary data", "170–300"],
        ["Item 9.", "Changes in and disagreements with accountants", "None"],
        ["Item 9A.", "Controls and procedures", "168"],
        ["Item 15.", "Exhibits, financial statement schedules", "310"],
    ]
    for row in index_rows:
        out.append(table([row]))  # one-row tables: recognized as (stub) Item headings
        if row[0] in ("Item 7.", "Item 8."):
            out.append(div("The information required by this Item is in the Annual Report."))
    out.append(div("Exhibit 21 lists the subsidiaries of Example Bank Corp."))
    out.append(div(f"For a discussion of results, see {header} on pages 50–160 of this report."))
    auditor = "Report of Independent Registered Public Accounting Firm"
    out.append(table([["Annual report contents", "Page"], [header, "50"], [auditor, "170"]]))
    out.append(page_break())
    out.append(div("Five-year summary of consolidated financial highlights", bold=True))
    out.append(data_table(rng, "Highlights"))
    out.append(div(paragraph(rng, 4)))

    page = 50
    for p in range(18):  # MD&A pages, each with the running header
        out.append(div(header, bold=True))
        if p == 0:
            out.append(
                div(
                    "The following is Management’s discussion and analysis of the financial "
                    "condition and results of operations (“MD&A”) of Example Bank Corp. for "
                    "the year ended December 31, 2025. " + paragraph(rng, 3)
                )
            )
        out += [div(paragraph(rng)) for _ in range(3)]
        out.append(data_table(rng, f"Segment {p}"))
        out.append(div(paragraph(rng, 4)))
        out.append(div(f"Example Bank Corp./2025 Form 10-K | {page}"))
        out.append(page_break())
        page += 1
    out.append(div("Management’s report on internal control over financial reporting", bold=True))
    out.append(div(paragraph(rng, 4)))
    out.append(div("Report of Independent Registered Public Accounting Firm", bold=True))
    out.append(div("To the Board of Directors and Stockholders: " + paragraph(rng, 4)))
    out.append(div("Consolidated statements of income", bold=True))
    out.append(data_table(rng, "Income"))
    for _ in range(10):  # notes pages, each with their own running header
        out.append(div(notes_header, bold=True))
        out += [div(paragraph(rng)) for _ in range(3)]
        out.append(div(f"Example Bank Corp./2025 Form 10-K | {page}"))
        out.append(page_break())
        page += 1
    out.append(div("Glossary of terms and acronyms", bold=True))
    out.append(div(paragraph(rng, 4)))
    return document("JPM-style cross-reference layout", out)


def energy_style() -> str:
    """XOM's layout: Item 7/8 point to a Financial Section placed after Item 16."""
    rng = random.Random(11)
    header = "MANAGEMENT’S DISCUSSION AND ANALYSIS OF FINANCIAL CONDITION AND RESULTS OF OPERATIONS"
    notes_header = "NOTES TO CONSOLIDATED FINANCIAL STATEMENTS"
    out = [div("UNITED STATES SECURITIES AND EXCHANGE COMMISSION"), div("FORM 10-K")]
    out.append(div("Example Energy Corporation"))
    out.append(table([["Items 1 and 2.", "Business", "1"], ["Item 7.", "MD&A", "40"]]))
    out.append(page_break())
    out += part_one(rng, combined_items=True)
    out += [div("PART II"), div("Item 5. Market for Registrant’s Common Equity", bold=True)]
    out.append(div(paragraph(rng, 3)))
    out.append(div("ITEM 7. " + header, bold=True))
    out.append(
        div(
            "Reference is made to the section entitled “Management’s Discussion and Analysis "
            "of Financial Condition and Results of Operations” in the Financial Section of "
            "this report."
        )
    )
    out.append(div("ITEM 8. FINANCIAL STATEMENTS AND SUPPLEMENTARY DATA", bold=True))
    out.append(
        div(
            "Reference is made to the following in the Financial Section: Report of "
            "Independent Registered Public Accounting Firm; Consolidated Financial Statements; "
            "Notes to Consolidated Financial Statements; Supplemental Information on Oil and "
            "Gas Exploration and Production Activities."
        )
    )
    out += [div("ITEM 9A. CONTROLS AND PROCEDURES", bold=True), div(paragraph(rng, 4))]
    out += [div("PART IV"), div("ITEM 15. EXHIBITS, FINANCIAL STATEMENT SCHEDULES", bold=True)]
    exhibits = [
        ["Exhibit", "Description"],
        ["3(i)", "Restated Certificate"],
        ["21", "Subsidiaries"],
    ]
    out.append(table(exhibits))
    out += [div("ITEM 16. FORM 10-K SUMMARY", bold=True), div("None.")]
    out.append(div("SIGNATURES", bold=True))
    out.append(
        div(
            "Pursuant to the requirements of Section 13 of the Securities Exchange Act of 1934, "
            "the registrant has duly caused this report to be signed on its behalf by the "
            "undersigned."
        )
    )
    out.append(page_break())
    out.append(div("FINANCIAL SECTION", bold=True))
    out.append(div("TABLE OF CONTENTS"))
    out.append(
        table(
            [
                ["Business Profile", "60"],
                ["Frequently Used Terms", "61"],
                [header.title(), "62"],
                ["Report of Independent Registered Public Accounting Firm", "69"],
                ["Consolidated Statement of Income", "72"],
                ["Notes to Consolidated Financial Statements", "78"],
            ]
        )
    )
    out.append(div("BUSINESS PROFILE", bold=True))
    out.append(data_table(rng, "Profile"))
    out += [div("FREQUENTLY USED TERMS", bold=True), div(paragraph(rng, 4))]
    page = 62
    for p in range(18):  # MD&A pages: running header, about 20-40 lines each
        out.append(div(header, bold=True))
        if p == 0:
            out.append(div("FUNCTIONAL EARNINGS SUMMARY", bold=True))
            out.append(data_table(rng, "Earnings"))
        out += [div(paragraph(rng)) for _ in range(3)]
        out.append(data_table(rng, f"Segment {p}"))
        out.append(div(paragraph(rng, 4)))
        out.append(div(str(page)))
        out.append(page_break())
        page += 1
    out += [div("REPORT OF MANAGEMENT", bold=True), div(paragraph(rng, 3))]
    out.append(div("REPORT OF INDEPENDENT REGISTERED PUBLIC ACCOUNTING FIRM", bold=True))
    out.append(div("To the Board of Directors and Shareholders: " + paragraph(rng, 4)))
    out.append(div("CONSOLIDATED STATEMENT OF INCOME", bold=True))
    out.append(data_table(rng, "Income"))
    for _ in range(10):  # notes pages
        out.append(div(notes_header, bold=True))
        out += [div(paragraph(rng)) for _ in range(3)]
        out.append(div(str(page)))
        out.append(page_break())
        page += 1
    out.append(div("SUPPLEMENTAL INFORMATION ON OIL AND GAS EXPLORATION AND PRODUCTION", bold=True))
    out.append(div(paragraph(rng, 4)))
    return document("XOM-style cross-reference layout", out)


def main() -> None:
    (HERE / "xref_bank_style.htm").write_text(bank_style(), encoding="utf-8")
    (HERE / "xref_energy_style.htm").write_text(energy_style(), encoding="utf-8")


if __name__ == "__main__":
    main()
